/**
 * Builds fixtures/projects/wiring-sample.json, the M6 acceptance panel, through the same
 * wiring ops the editor uses. Run with `npm run gen:wiring-sample` (through Vitest, which
 * resolves the catalogue's bundler imports); the file is committed and not regenerated by
 * `npm run gen`, because wire ids are random.
 *
 * Battery, master switch, four fuses, and instruments; data links between the FLARM, the
 * vario and the flight computer; radio with speaker, PTT and antenna; pitot, static and TE
 * to the instruments through tees. Every part is generic (placeholder data, unverified).
 */
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { Project, type PlacedPart, type Terminal } from '../src/model/schema';
import { withConnections, addRouteOps } from '../src/wiring/ops';
import { applyOps } from '../src/store/doc';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

const part = (id: string, gen: string, x: number, y: number, label: string, extra: Partial<PlacedPart> = {}): PlacedPart => ({
  id,
  part: { id: gen, version: 1 },
  x,
  y,
  rotation: 0,
  label,
  mountedTo: null,
  depthOffset: 0,
  locked: false,
  offPanelRunMm: null,
  ...extra,
});

export function buildWiringSample(): Project {
let doc = Project.parse({
  schemaVersion: 1,
  id: 'wiring-sample',
  name: 'Wiring sample panel',
  gliderType: 'Sample',
  created: '2026-10-11T00:00:00.000Z',
  modified: '2026-10-11T00:00:00.000Z',
  template: { ref: { id: 'sample.rect-300x200', version: 1 } },
  settings: { minLigamentMm: 5, minEdgeDistanceMm: 8, minBendDistanceMm: 10 },
  parts: [
    part('asi', 'generic.asi-80', -95, 40, 'ASI'),
    part('vario', 'generic.vario-electric-57', 0, 50, 'Vario'),
    part('alt', 'generic.altimeter-80', 95, 40, 'Altimeter'),
    part('radio', 'generic.radio-57', -95, -35, 'Radio'),
    part('fc', 'generic.flight-computer', 45, -55, 'Flight computer', { params: { cutoutW: 100, cutoutH: 70 } }),
    part('flarm', 'generic.flarm-unit', 45, -55, 'FLARM', { mountedTo: { parent: 'fc', dx: 0, dy: 0, dz: 45 } }),
    part('ms', 'generic.toggle-switch', -130, -85, 'Master'),
    part('f1', 'generic.fuse-holder', -108, -85, 'F1 Vario', { params: { ratingA: 2 } }),
    part('f2', 'generic.fuse-holder', -86, -85, 'F2 FLARM', { params: { ratingA: 2 } }),
    part('f3', 'generic.fuse-holder', -64, -85, 'F3 Flight computer', { params: { ratingA: 3 } }),
    part('f4', 'generic.fuse-holder', -42, -85, 'F4 Radio', { params: { ratingA: 5 } }),
    // Off the panel: positions are where the loom leaves the panel, in the rear view, 130 mm
    // back (behind everything on the panel).
    part('bat', 'generic.battery', -140, -95, 'Battery', { depthOffset: 130, offPanelRunMm: 1500 }),
    part('f0', 'generic.inline-fuse', -140, -95, 'F0 Main', { depthOffset: 130, offPanelRunMm: 1450, params: { ratingA: 5 } }),
    part('spk', 'generic.speaker', 140, 95, 'Speaker', { depthOffset: 130, offPanelRunMm: 400 }),
    part('ptt', 'generic.ptt', -140, -95, 'Stick PTT', { depthOffset: 130, offPanelRunMm: 900 }),
    part('vhf', 'generic.antenna', 140, -95, 'VHF antenna', { depthOffset: 130, offPanelRunMm: 2500 }),
    part('fant', 'generic.antenna', 140, 95, 'FLARM antenna', { depthOffset: 130, offPanelRunMm: 300 }),
    part('pitot', 'generic.pitot', -140, 95, 'Pitot', { depthOffset: 130, offPanelRunMm: 1200 }),
    part('static', 'generic.static', -140, 95, 'Static', { depthOffset: 130, offPanelRunMm: 2000 }),
    part('te', 'generic.te-probe', 140, 95, 'TE probe', { depthOffset: 130, offPanelRunMm: 3500 }),
    part('tee1', 'generic.tee', -50, 60, 'Pitot tee'),
    part('tee2', 'generic.tee', -50, 20, 'Static tee 1'),
    part('tee3', 'generic.tee', 50, 20, 'Static tee 2'),
  ],
});

const pin = (p: string, c: string, n: string): Terminal => ({ part: p, connector: c, pin: n });
const port = (p: string, n: string): Terminal => ({ part: p, port: n });

doc = withConnections(doc, [
  // Power: battery → main fuse → master switch → fuse bus → each load.
  [pin('bat', 'T', '+'), pin('f0', 'T', 'LINE')],
  [pin('f0', 'T', 'LOAD'), pin('ms', 'T', '1')],
  [pin('ms', 'T', '2'), pin('f1', 'T', 'LINE')],
  [pin('f1', 'T', 'LINE'), pin('f2', 'T', 'LINE')],
  [pin('f2', 'T', 'LINE'), pin('f3', 'T', 'LINE')],
  [pin('f3', 'T', 'LINE'), pin('f4', 'T', 'LINE')],
  [pin('f1', 'T', 'LOAD'), pin('vario', 'PWR', '+')],
  [pin('f2', 'T', 'LOAD'), pin('flarm', 'PWR', '+')],
  [pin('f3', 'T', 'LOAD'), pin('fc', 'PWR', '+')],
  [pin('f4', 'T', 'LOAD'), pin('radio', 'PWR', '+')],
  // Grounds back to the battery.
  [pin('vario', 'PWR', 'GND'), pin('bat', 'T', '-')],
  [pin('flarm', 'PWR', 'GND'), pin('bat', 'T', '-')],
  [pin('fc', 'PWR', 'GND'), pin('bat', 'T', '-')],
  [pin('radio', 'PWR', 'GND'), pin('bat', 'T', '-')],
  // Data: FLARM port 1 to the vario, port 2 to the flight computer, TX to RX.
  [pin('flarm', 'P1', 'TX'), pin('vario', 'DATA', 'RX')],
  [pin('vario', 'DATA', 'TX'), pin('flarm', 'P1', 'RX')],
  [pin('flarm', 'P1', 'GND'), pin('vario', 'DATA', 'GND')],
  [pin('flarm', 'P2', 'TX'), pin('fc', 'DATA', 'RX')],
  [pin('fc', 'DATA', 'TX'), pin('flarm', 'P2', 'RX')],
  [pin('flarm', 'P2', 'GND'), pin('fc', 'DATA', 'GND')],
  // Audio, PTT and antennas.
  [pin('radio', 'AUD', 'SPK+'), pin('spk', 'T', '+')],
  [pin('radio', 'AUD', 'SPK-'), pin('spk', 'T', '-')],
  [pin('radio', 'AUD', 'PTT'), pin('ptt', 'T', '1')],
  [pin('ptt', 'T', '2'), pin('bat', 'T', '-')],
  [pin('radio', 'ANT', 'RF'), pin('vhf', 'ANT', 'RF')],
  [pin('flarm', 'ANT', 'RF'), pin('fant', 'ANT', 'RF')],
  // Pneumatics: pitot to ASI and vario; static to ASI, altimeter and vario; TE to the vario.
  [port('pitot', 'P'), port('tee1', 'A')],
  [port('tee1', 'B'), port('asi', 'P')],
  [port('tee1', 'C'), port('vario', 'P')],
  [port('static', 'S'), port('tee2', 'A')],
  [port('tee2', 'B'), port('asi', 'S')],
  [port('tee2', 'C'), port('tee3', 'A')],
  [port('tee3', 'B'), port('alt', 'S')],
  [port('tee3', 'C'), port('vario', 'S')],
  [port('te', 'TE'), port('vario', 'TE')],
]);

// The main loom: from the battery exit at the bottom left, along the bottom of the panel
// 130 mm behind it (clear of every part), up the right-hand side.
const loom = addRouteOps(
  [
    { x: -140, y: -95, z: 130 },
    { x: -140, y: -75, z: 130 },
    { x: 120, y: -75, z: 130 },
    { x: 120, y: 60, z: 130 },
  ],
  'Main loom',
);
doc = applyOps(doc, loom.ops)[0];
const onLoom = doc.wires.filter((w) => ['power', 'ground'].includes(doc.nets.find((n) => n.id === w.net)!.type)).map((w) => w.id);
doc = { ...doc, wires: doc.wires.map((w) => (onLoom.includes(w.id) ? { ...w, route: loom.route.id } : w)) };

return Project.parse(doc);
}

export function writeWiringSample() {
  const doc = buildWiringSample();
  const out = join(root, 'fixtures', 'projects', 'wiring-sample.json');
  writeFileSync(out, JSON.stringify(doc, null, 2) + '\n');
  return out;
}
